93	// identifier is already present. Exactly one concurrent caller observes
94	// created == true for a given object. Newly stored objects register their
95	// unique chunks in the shared block table; repeated chunks within the
96	// object and chunks shared with other objects are stored only once.
97	func (s *store) put(obj *object) (stored *object, created bool) {
98		s.mu.Lock()
99		defer s.mu.Unlock()
100		if existing, ok := s.objects[obj.cid]; ok {
101			return existing, false
102		}
103		s.objects[obj.cid] = obj
104		seen := make(map[string]bool, len(obj.cids))
105		for i, c := range obj.cids {
106			if b, ok := s.blocks[c]; ok {
107				obj.chunks[i] = b.data // share the stored copy
108				if !seen[c] {
109					b.refs++
110				}
111			} else {
112				s.blocks[c] = &blockRef{data: obj.chunks[i], refs: 1}
113			}
114			seen[c] = true
115		}
116		return obj, true
