160	// setPin pins cid with the given expiration, replacing any previous pin. It
161	// reports ok == false when the object does not exist. created is true when
162	// no valid pin was in force at now. The check and the update are atomic
163	// with respect to garbage collection.
164	func (s *store) setPin(cid string, expiresAt *time.Time, now time.Time) (created, ok bool) {
165		s.mu.Lock()
166		defer s.mu.Unlock()
167		if _, exists := s.objects[cid]; !exists {
