		case string:
			if n := len(stack); n > 0 && stack[n-1].object {
				top := stack[n-1]
				if top.wantKey {
					if top.keys[t] {
						return errInvalidBundle
					}
					top.keys[t] = true
					top.wantKey = false
				} else {
					top.wantKey = true
				}
			}
		default: // number, boolean or null value
			if n := len(stack); n > 0 && stack[n-1].object {
				stack[n-1].wantKey = true
			}
		}
	}
}

