119	func chunkData(body []byte) ([]string, map[string][]byte) {
120		chunks := []string{}
121		data := map[string][]byte{}
122		for start := 0; start < len(body); start += ChunkSize {
123			end := start + ChunkSize
124			if end > len(body) {
125				end = len(body)
126			}
127			chunk := body[start:end]
128			sum := sha256.Sum256(chunk)
129			cid := "sha256:" + hex.EncodeToString(sum[:])
130			chunks = append(chunks, cid)
131			data[cid] = chunk
132		}
133		return chunks, data
134	}
