70	// getBundle handles GET /v1/bundles/{cid}.
71	func (s *store) getBundle(w http.ResponseWriter, r *http.Request) {
72		if r.Method != http.MethodGet {
73			w.Header().Set("Allow", http.MethodGet)
74			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
75			return
76		}
77		obj := s.lookupObject(w, r)
78		if obj == nil {
79			return
80		}
81		unique := make(map[string][]byte, len(obj.cids))
82		for i, c := range obj.cids {
83			if _, ok := unique[c]; !ok {
84				unique[c] = obj.chunks[i]
85			}
86		}
87		cids := make([]string, 0, len(unique))
88		for c := range unique {
89			cids = append(cids, c)
90		}
91		sort.Strings(cids)
92		blocks := make([]bundleBlock, 0, len(cids))
93		for _, c := range cids {
94			blocks = append(blocks, bundleBlock{CID: c, Data: base64.StdEncoding.EncodeToString(unique[c])})
95		}
96		w.Header().Set("Content-Type", bundleMediaType)
97		_ = json.NewEncoder(w).Encode(bundleDocument{
98			Version: bundleVersion,
99			Root: bundleRoot{
100				CID:       obj.cid,
101				Size:      obj.size,
102				ChunkSize: ChunkSize,
103				Chunks:    obj.cids,
104			},
105			Blocks: blocks,
106		})
107	}
