109	// postBundle handles POST /v1/bundles.
110	func (s *store) postBundle(w http.ResponseWriter, r *http.Request) {
111		if r.Method != http.MethodPost {
112			w.Header().Set("Allow", http.MethodPost)
113			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
114			return
115		}
116		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
117		if err != nil || mediaType != bundleMediaType {
118			writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
119			return
120		}
121		body, err := io.ReadAll(io.LimitReader(r.Body, maxBundleSize+1))
122		if err != nil {
123			writeError(w, http.StatusBadRequest, "invalid_bundle")
124			return
125		}
126		if len(body) > maxBundleSize {
127			writeError(w, http.StatusRequestEntityTooLarge, "payload_too_large")
128			return
129		}
130		doc, err := parseBundle(body)
131		if err != nil {
132			writeError(w, http.StatusBadRequest, "invalid_bundle")
133			return
134		}
135		root := doc.Root
136		if *root.Size < 0 {
137			writeError(w, http.StatusBadRequest, "invalid_bundle")
138			return
139		}
140		if !validCID(*root.CID) {
141			writeError(w, http.StatusBadRequest, "invalid_bundle")
142			return
143		}
144		for _, c := range root.Chunks {
145			if !validCID(c) {
146				writeError(w, http.StatusBadRequest, "invalid_bundle")
147				return
148			}
149		}
150		blocks := make(map[string][]byte, len(doc.Blocks))
151		duplicateBlock := false
152		for i := range doc.Blocks {
153			cid, encoded := *doc.Blocks[i].CID, *doc.Blocks[i].Data
154			if !validCID(cid) {
155				writeError(w, http.StatusBadRequest, "invalid_bundle")
156				return
157			}
158			data, err := base64.StdEncoding.DecodeString(encoded)
159			if err != nil {
160				writeError(w, http.StatusBadRequest, "invalid_bundle")
161				return
162			}
163			if _, exists := blocks[cid]; exists {
164				duplicateBlock = true
165			}
166			blocks[cid] = data
167		}
168		if *doc.Version != bundleVersion || *root.ChunkSize != ChunkSize {
169			writeError(w, http.StatusUnprocessableEntity, "unsupported_bundle")
170			return
171		}
172		if *root.Size > MaxObjectSize {
173			writeError(w, http.StatusRequestEntityTooLarge, "payload_too_large")
174			return
175		}
176		if err := verifyBundleIntegrity(root, blocks, duplicateBlock); err != nil {
177			if errors.Is(err, errBundleTooLarge) {
178				writeError(w, http.StatusRequestEntityTooLarge, "payload_too_large")
179			} else {
180				writeError(w, http.StatusUnprocessableEntity, "integrity_check_failed")
181			}
182			return
183		}
