208	// verifyBundleIntegrity checks the content-addressed invariants of a
209	// structurally valid bundle: block digests, the exact block set, the fixed
210	// chunking layout, the rebuilt length and the root identifier.
211	func verifyBundleIntegrity(root *bundleRootInput, blocks map[string][]byte, duplicateBlock bool) error {
212		for cid, data := range blocks {
213			if chunkCID(data) != cid {
214				return errInvalidBundle
215			}
216		}
217		referenced := make(map[string]bool, len(root.Chunks))
218		for _, c := range root.Chunks {
219			referenced[c] = true
220		}
221		if duplicateBlock || len(blocks) != len(referenced) {
222			return errInvalidBundle
223		}
224		for c := range referenced {
225			if _, ok := blocks[c]; !ok {
226				return errInvalidBundle
227			}
228		}
229		total := 0
230		for i, c := range root.Chunks {
231			n := len(blocks[c])
232			if i+1 < len(root.Chunks) && n != ChunkSize {
233				return errInvalidBundle
234			}
235			total += n
236			if total > MaxObjectSize {
237				return errBundleTooLarge
238			}
239		}
240		if n := len(root.Chunks); n > 0 {
241			if last := len(blocks[root.Chunks[n-1]]); last == 0 || last > ChunkSize {
242				return errInvalidBundle
243			}
244		}
245		if total != int(*root.Size) {
246			return errInvalidBundle
247		}
248		if rootCID(int(*root.Size), root.Chunks) != *root.CID {
249			return errInvalidBundle
250		}
251		return nil
252	}
